import sys
import os
import subprocess
from concurrent.futures import ThreadPoolExecutor, as_completed
from datetime import datetime

def read_commands(file_path):
    try:
        with open(file_path, 'r') as file:
            return [line.strip() for line in file if line.strip()]
    except FileNotFoundError:
        print(f"Error: Input file '{file_path}' not found.", file=sys.stderr)
        sys.exit(1)

def execute_command(command):
    try:
        result = subprocess.run(
            command,
            shell=True,
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        return command, result.stdout, result.stderr, result.returncode
    except subprocess.CalledProcessError as e:
        return command, "", e.stderr, e.returncode

def generate_html_report(commands, output_path):
    html_content = f"""<!DOCTYPE html>
<html>
<head>
    <title>Command Report</title>
    <style>
        table {{
            border-collapse: collapse;
            width: 100%;
        }}
        th, td {{
            border: 1px solid #ddd;
            padding: 8px;
            text-align: left;
        }}
        th {{
            background-color: #f2f2f2;
        }}
        pre {{
            white-space: pre-wrap;
            word-wrap: break-word;
        }}
    </style>
</head>
<body>
    <h1>Command Execution Report</h1>
    <table>
        <thead>
            <tr>
                <th>Command</th>
                <th>Standard Output</th>
                <th>Standard Error</th>
                <th>Exit Code</th>
            </tr>
        </thead>
        <tbody>
"""
    for cmd, stdout, stderr, exit_code in commands:
        html_content += f"""
            <tr>
                <td><pre>{cmd}</pre></td>
                <td><pre>{stdout}</pre></td>
                <td><pre>{stderr}</pre></td>
                <td><pre>{exit_code}</pre></td>
            </tr>
"""
    html_content += """
        </tbody>
    </table>
</body>
</html>
"""
    with open(output_path, 'w') as file:
        file.write(html_content)

def main():
    if len(sys.argv) != 3:
        print("Usage: python run_and_report.py <input_file> <output_html>", file=sys.stderr)
        sys.exit(1)

    input_file = sys.argv[1]
    output_file = sys.argv[2]

    commands = read_commands(input_file)

    with ThreadPoolExecutor(max_workers=4) as executor:
        futures = {executor.submit(execute_command, cmd): cmd for cmd in commands}
        results = []
        for future in as_completed(futures):
            results.append(future.result())

    generate_html_report(results, output_file)

if __name__ == "__main__":
    main()

import argparse
import concurrent.futures
import os
import subprocess
import sys
from html import escape

def execute_command(cmd):
    try:
        process = subprocess.Popen(
            cmd,
            shell=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        stdout, stderr = process.communicate()
        return cmd, stdout, stderr, process.returncode
    except Exception as e:
        return cmd, "", str(e), 1

def process_commands(input_file, output_file):
    if not os.path.exists(input_file):
        print(f"Error: Input file '{input_file}' does not exist.", file=sys.stderr)
        sys.exit(1)

    with open(input_file, 'r') as f:
        commands = [line.strip() for line in f if line.strip()]

    with concurrent.futures.ThreadPoolExecutor(max_workers=4) as executor:
        futures = [executor.submit(execute_command, cmd) for cmd in commands]
        results = [future.result() for future in concurrent.futures.as_completed(futures)]

    html_content = f"""<!DOCTYPE html>
<html>
<head>
    <title>Command Report</title>
    <style>
        table {{
            border-collapse: collapse;
            width: 100%;
        }}
        th, td {{
            border: 1px solid #ddd;
            padding: 8px;
            text-align: left;
        }}
        th {{
            background-color: #f2f2f2;
        }}
        pre {{
            white-space: pre-wrap;
            word-wrap: break-word;
        }}
    </style>
</head>
<body>
    <h1>Command Execution Report</h1>
    <table>
        <thead>
            <tr>
                <th>Command</th>
                <th>Standard Output</th>
                <th>Standard Error</th>
                <th>Exit Code</th>
            </tr>
        </thead>
        <tbody>
"""

    for cmd, stdout, stderr, exit_code in results:
        html_content += f"""
            <tr>
                <td><pre>{escape(cmd)}</pre></td>
                <td><pre>{escape(stdout) if stdout else 'None'}</pre></td>
                <td><pre>{escape(stderr) if stderr else 'None'}</pre></td>
                <td><pre>{exit_code}</pre></td>
            </tr>
"""

    html_content += """
        </tbody>
    </table>
</body>
</html>
"""

    with open(output_file, 'w') as f:
        f.write(html_content)

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description='Execute shell commands and generate an HTML report.')
    parser.add_argument('input_file', help='Path to the input text file containing commands')
    parser.add_argument('output_file', help='Path to the output HTML file')
    args = parser.parse_args()

    process_commands(args.input_file, args.output_file)
